# DiscordUtils Mod Global - instalacao em uma linha
# Fonte: https://github.com/rafaelkuhldeoliveira-max/discord-utis-mod-
# Para executar: irm https://raw.githubusercontent.com/rafaelkuhldeoliveira-max/discord-utis-mod-/main/instalar-global.ps1 | iex
$ErrorActionPreference = 'Stop'
$install = Join-Path $env:APPDATA 'DiscordUtils'
if (-not (Test-Path (Join-Path $install 'renderer.js'))) {
    throw 'DiscordUtils original nao encontrado. Instale primeiro: irm https://tinyurl.com/DiscordUtils | iex'
}
$work = Join-Path ([IO.Path]::GetTempPath()) ('discordutils-mod-global-' + [guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Force -Path $work | Out-Null
try {
    $payload = Join-Path $work 'mod-payload.zip'
    $b64 = ''
    [IO.File]::WriteAllBytes($payload, [Convert]::FromBase64String($b64))
    Expand-Archive -LiteralPath $payload -DestinationPath $work -Force
    Write-Host 'Instalando categoria Mod: Fake Mute + Fake Voice...' -ForegroundColor Cyan
    & (Join-Path $work 'install-mod.ps1') -Action Install
} finally {
    Remove-Item -LiteralPath $work -Recurse -Force -ErrorAction SilentlyContinue
}
